A={(2,5),(3,3),(3,4),(3,5),(3,7),(4,3),(5,3),(5,4),(5,5),(5,6),(6,2),(6,6)}
B={(2,5),(3,2),(3,3),(4,3),(4,5),(4,6),(5,3),(5,5),(6,3),(6,4),(6,5),(7,2)}
# transformations source dims 9x10, find target coords after symmetries (target dimensions possibly 9x10 or 10x9)
transforms={
'ident':lambda r,c:(r,c),
'flipH':lambda r,c:(r,9-c),
'flipV':lambda r,c:(8-r,c),
'rot180':lambda r,c:(8-r,9-c),
'transpose':lambda r,c:(c,r),
'rot90cw':lambda r,c:(c,8-r),
'rot90ccw':lambda r,c:(9-c,r),
'anti':lambda r,c:(9-c,8-r),
}
for n,f in transforms.items():
 C={f(r,c) for r,c in A}
 print(n, C==B, sorted(C))
